def parse_line(line):
    name, marks_text = line.split(":", 1)
    name = name.strip()
    marks = []
    for piece in marks_text.split(","):
        piece = piece.strip()
        if piece != "":
            marks.append(int(piece))
    return name, marks


def average(marks):
    if len(marks) == 0:
        return 0.0
    return round(sum(marks) / len(marks), 2)


def ranking(lines):
    pairs = []
    for line in lines:
        if line.strip() == "":
            continue
        name, marks = parse_line(line)
        pairs.append((name, average(marks)))
    return sorted(pairs, key=lambda pair: (-pair[1], pair[0]))

